def _forms(rel: str) -> tuple:
    """書いた形・揃えた形・実物の場所の3つ（大文字と小文字は呼ぶ側で揃える）。"""
    raw = (rel or "").strip().strip("`")
    return (raw, os.path.normpath(raw), os.path.realpath(repo_path(raw)))


def never_write(rel: str) -> bool:
    # 守りの仕組みか（いつも書かない相手）。書いた形・揃えた形・実物の場所の3つで見る（大文字と小文字は区別しない）。
    # ★2026-09-24（監査 CP42 の A4）＝直す前は書いた文字のままを見たので、「.claude/./hooks/x.sh」と書くと
    #   一覧に当たらず、TARGET の縛り（揃えた形で照らす）も通って、hook に書けた（写しで実測）。
    return any(k.lower() in f.replace(os.sep, "/").lower() for f in _forms(rel) for k in NEVER_WRITE)


def guarded(rel: str) -> bool:
    """hook・道具・壊すプログラムか（2026-09-29）＝承認済みの設計書の TARGET・NEW_FILE に在るときだけ当てる相手。"""
    return any(k.lower() in f.replace(os.sep, "/").lower() for f in _forms(rel) for k in GUARDED)

