def command_argv(f: dict):
    """走らせるコマンドの件が、道具が走らせてよい形なら [python, 道具, 旗…] を返す（2026-09-29）。RUN_OK に無ければ None。

    ★通すのは「python3 <…/>.claude/tools/<道具> <旗>」の1行だけ（つなぎ・書き出し・置き換えの記号が在れば通さない）。
    """
    cmds = [b for _a, k, b in (f.get("4つ目") or []) if k == "走らせるコマンド"]
    if len(cmds) != 1:
        return None
    cmd = cmds[0].strip()
    if any(c in cmd for c in (";", "&", "|", ">", "<", "`", "$", "\n")):
        return None
    toks = cmd.split()
    if len(toks) < 2 or toks[0] != "python3":
        return None
    tool = toks[1].rsplit("/", 1)[-1]
    if not re.fullmatch(r"(?:\S*/)?\.claude/tools/" + re.escape(tool), toks[1]):
        return None
    if tuple(toks[2:]) not in RUN_OK.get(tool, set()):
        return None
    return [sys.executable, os.path.join(ROOT, ".claude", "tools", tool)] + toks[2:]


def run_commands(items: list, wrote_src: bool) -> int:
    """作り直しのコマンドを走らせる（2026-09-29・同じコマンドは1回）。戻り＝0 以外の終了コードが在れば 1。

    ★元データ（acceptance_src.json）に当てたときは、そのコマンドが監査結果に無くても設計書を作り直す（wrote_src）。
    ★RUN_OK に無いコマンドは走らせず、打つべきコマンドとして出す（承認・rm など＝まこさんか CC が打つ）。
    """
    todo, rc = [], 0
    for f in items:
        argv = command_argv(f)
        if argv and argv not in todo:
            todo.append(argv)
    ga = [sys.executable, os.path.join(ROOT, ".claude", "tools", "gen_acceptance.py"), "--write"]
    if wrote_src and ga not in todo:
        todo.append(ga)
    for argv in todo:
        r = subprocess.run(argv, cwd=ROOT, capture_output=True, text=True)
        last = ((r.stdout or "") + (r.stderr or "")).strip().splitlines()[-1:]
        print(f"   ▶ 走らせた: {os.path.basename(argv[1])} {' '.join(argv[2:])} → rc={r.returncode}"
              + (f"（{last[0][:120]}）" if last else ""))
        if r.returncode:
            rc = 1
    for f in items:
        if not command_argv(f):
            cmd = next((b for _a, k, b in (f.get("4つ目") or []) if k == "走らせるコマンド"), "")
            print(f"   ⏸ 修正 {f['番号']}: 道具は走らせない（作り直しのコマンドの一覧に無い）＝打つべきコマンド: {cmd.strip()[:120]}")
    return rc


